import type { AdminPortalUser } from '../constants/adminPortal';

export const getAdminPortalUser = (): AdminPortalUser | null => {
  if (typeof window === 'undefined') {
    return null;
  }

  const raw = localStorage.getItem('adminUser');
  if (!raw) {
    return null;
  }

  try {
    return JSON.parse(raw) as AdminPortalUser;
  } catch {
    return null;
  }
};

export const persistAdminPortalSession = (user: AdminPortalUser, token: string): void => {
  if (typeof window === 'undefined') {
    return;
  }

  localStorage.setItem('token', token);
  localStorage.setItem('adminUser', JSON.stringify(user));
};

export const clearAdminPortalSession = (): void => {
  if (typeof window === 'undefined') {
    return;
  }

  localStorage.removeItem('token');
  localStorage.removeItem('adminUser');
};
