import React, { useState, useEffect } from "react";
import { useForm, Controller } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import {
  Paper,
  Typography,
  TextField,
  Button,
  Box,
  Alert,
  CircularProgress,
  Stack,
  Link,
  Divider,
  InputAdornment,
  IconButton,
  Chip,
} from "@mui/material";
import {
  Visibility,
  VisibilityOff,
  Login as LoginIcon,
  LockOutlined,
  EmailOutlined,
} from "@mui/icons-material";
import { useNavigate, Link as RouterLink, useSearchParams } from "react-router-dom";
import { alpha, useTheme } from "@mui/material/styles";
import { useRegistration } from "../context/RegistrationContext";
import ApiService from "../services/api";
import { BASELINE_SOFTWARE_VERSION } from "../constants/version";
import BrandLogoMark from "./BrandLogoMark";
import { AccountPathway } from "../constants/accountTypes";
import {
  resolveAuthenticatedHomePath,
  resolveMsmePostLoginDestination,
} from "../utils/resolvePostLoginDestination";
import {
  billingPathForPlanIntent,
  clearPendingBillingPlanId,
  getPendingBillingPlanId,
  setPendingBillingPlanId,
} from "../utils/billingPlanIntent";

const loginSchema = yup.object({
  email: yup
    .string()
    .email("Invalid email format")
    .required("Email is required"),
  password: yup.string().required("Password is required"),
});

type LoginFormData = {
  email: string;
  password: string;
};

const PORTAL_ROLES = [
  { label: "MSME", description: "Carbon workspace" },
  { label: "Admin", description: "Platform administration" },
  { label: "Reviewer", description: "Auditors & verification" },
  { label: "Partner", description: "API integrations" },
] as const;

const UserLogin: React.FC = () => {
  const theme = useTheme();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { login, isRegistered, setAccountPathway } = useRegistration();
  const selectedPathway: AccountPathway = "msme";
  const selectedPlanId = searchParams.get("plan")?.trim() || null;
  const [isLoggingIn, setIsLoggingIn] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [showPassword, setShowPassword] = useState(false);
  const [baselineVersion, setBaselineVersion] = useState<string>(BASELINE_SOFTWARE_VERSION);

  const {
    control,
    handleSubmit,
    formState: { errors },
  } = useForm<LoginFormData>({
    resolver: yupResolver(loginSchema),
    defaultValues: {
      email: "",
      password: "",
    },
    mode: "onBlur",
  });

  useEffect(() => {
    setAccountPathway("msme");
  }, [setAccountPathway]);

  useEffect(() => {
    if (selectedPlanId) {
      setPendingBillingPlanId(selectedPlanId);
    }
  }, [selectedPlanId]);

  useEffect(() => {
    if (isRegistered) {
      navigate(resolveAuthenticatedHomePath());
    }
  }, [isRegistered, navigate]);

  useEffect(() => {
    let isMounted = true;

    const loadBaselineVersion = async () => {
      try {
        const versionMetadata = await ApiService.getVersionMetadata();
        if (isMounted) {
          setBaselineVersion(
            versionMetadata.baselineCodebaseVersion || BASELINE_SOFTWARE_VERSION,
          );
        }
      } catch (error) {
        if (isMounted) {
          setBaselineVersion(BASELINE_SOFTWARE_VERSION);
        }
      }
    };

    loadBaselineVersion();

    return () => {
      isMounted = false;
    };
  }, []);

  const onSubmit = async (data: LoginFormData) => {
    setLoginError(null);
    setIsLoggingIn(true);

    try {
      setAccountPathway(selectedPathway);
      const redirectPath = await login(data.email, data.password, selectedPathway);
      if (redirectPath) {
        navigate(redirectPath);
        return;
      }

      const msmeDestination = await resolveMsmePostLoginDestination();
      const pendingPlanId = getPendingBillingPlanId();
      if (pendingPlanId && msmeDestination === "/dashboard") {
        clearPendingBillingPlanId();
        navigate(billingPathForPlanIntent(pendingPlanId));
        return;
      }
      navigate(msmeDestination);
    } catch (error) {
      setLoginError(
        error instanceof Error
          ? error.message
          : "Login failed. Please check your credentials and try again.",
      );
    } finally {
      setIsLoggingIn(false);
    }
  };

  const handleTogglePasswordVisibility = () => {
    setShowPassword((prev) => !prev);
  };

  const isDark = theme.palette.mode === "dark";

  return (
    <Box
      sx={{
        minHeight: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        py: 4,
        px: 2,
        ...(isDark
          ? {
              backgroundColor: theme.palette.background.default,
              backgroundImage: `radial-gradient(ellipse 120% 80% at 0% -20%, ${alpha(theme.palette.primary.main, 0.16)} 0%, transparent 55%), radial-gradient(ellipse 100% 60% at 100% 0%, ${alpha(theme.palette.secondary.main, 0.08)} 0%, transparent 50%)`,
            }
          : {
              background: "linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%)",
            }),
      }}
    >
      <Paper
        elevation={3}
        sx={{
          maxWidth: 520,
          width: "100%",
          p: { xs: 3, sm: 5 },
          borderRadius: 3,
          background:
            theme.palette.mode === "light"
              ? "linear-gradient(135deg, #ffffff 0%, #f8fafc 100%)"
              : `linear-gradient(160deg, ${theme.palette.background.paper} 0%, ${alpha(theme.palette.common.white, 0.04)} 100%)`,
          border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.28 : 0.12)}`,
        }}
      >
        <Box sx={{ textAlign: "center", mb: 4 }}>
          <BrandLogoMark width={260} sx={{ mb: 2 }} />
          <Typography
            variant="h4"
            component="h1"
            gutterBottom
            sx={{
              fontWeight: 700,
              background: "linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)",
              backgroundClip: "text",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
            }}
          >
            Carbon Intelligence Portal
          </Typography>
          <Typography variant="body1" color="text.secondary" sx={{ mb: 2 }}>
            One sign-in for all account types — we route you to the right workspace automatically.
          </Typography>
          <Stack
            direction="row"
            spacing={1}
            useFlexGap
            flexWrap="wrap"
            justifyContent="center"
          >
            {PORTAL_ROLES.map((role) => (
              <Chip
                key={role.label}
                label={role.label}
                size="small"
                variant="outlined"
                title={role.description}
                sx={{ borderColor: alpha(theme.palette.primary.main, 0.35) }}
              />
            ))}
          </Stack>
        </Box>

        {loginError && (
          <Alert severity="error" sx={{ mb: 3 }}>
            {loginError}
          </Alert>
        )}

        <form onSubmit={handleSubmit(onSubmit)}>
          <Stack spacing={3}>
            <Controller
              name="email"
              control={control}
              render={({ field }) => (
                <TextField
                  {...field}
                  fullWidth
                  label="Email Address"
                  type="email"
                  autoComplete="email"
                  error={!!errors.email}
                  helperText={errors.email?.message}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <EmailOutlined color="action" />
                      </InputAdornment>
                    ),
                  }}
                />
              )}
            />

            <Controller
              name="password"
              control={control}
              render={({ field }) => (
                <TextField
                  {...field}
                  fullWidth
                  label="Password"
                  type={showPassword ? "text" : "password"}
                  autoComplete="current-password"
                  error={!!errors.password}
                  helperText={errors.password?.message}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <LockOutlined color="action" />
                      </InputAdornment>
                    ),
                    endAdornment: (
                      <InputAdornment position="end">
                        <IconButton
                          onClick={handleTogglePasswordVisibility}
                          edge="end"
                          aria-label="toggle password visibility"
                        >
                          {showPassword ? <VisibilityOff /> : <Visibility />}
                        </IconButton>
                      </InputAdornment>
                    ),
                  }}
                />
              )}
            />

            <Box sx={{ textAlign: "right" }}>
              <Link
                component={RouterLink}
                to="/forgot-password"
                variant="body2"
                sx={{
                  color: "primary.main",
                  textDecoration: "none",
                  "&:hover": {
                    textDecoration: "underline",
                  },
                }}
              >
                Forgot password?
              </Link>
            </Box>

            <Button
              type="submit"
              variant="contained"
              size="large"
              disabled={isLoggingIn}
              startIcon={
                isLoggingIn ? (
                  <CircularProgress size={20} color="inherit" />
                ) : (
                  <LoginIcon />
                )
              }
              sx={{
                py: 1.5,
                background: "linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)",
                "&:hover": {
                  background:
                    "linear-gradient(135deg, #43a047 0%, #1b5e20 100%)",
                },
                "&:disabled": {
                  backgroundColor: theme.palette.action.disabledBackground,
                  color: theme.palette.action.disabled,
                },
              }}
            >
              {isLoggingIn ? "Signing in..." : "Sign In"}
            </Button>
          </Stack>
        </form>

        <Divider sx={{ my: 4 }}>
          <Typography variant="body2" color="text.secondary">
            OR
          </Typography>
        </Divider>

        <Box sx={{ textAlign: "center" }}>
          <Typography variant="body2" color="text.secondary" gutterBottom>
            New MSME? Create your carbon workspace account.
          </Typography>
          <Button
            component={RouterLink}
            to={`/register?type=msme${selectedPlanId ? `&plan=${encodeURIComponent(selectedPlanId)}` : ""}`}
            variant="outlined"
            size="large"
            sx={{
              py: 1.5,
              borderColor: "success.main",
              color: "success.main",
              "&:hover": {
                borderColor: "success.dark",
                backgroundColor: alpha(theme.palette.success.main, isDark ? 0.14 : 0.06),
              },
            }}
          >
            Register as MSME
          </Button>
        </Box>

        <Box
          sx={{
            mt: 4,
            p: 3,
            borderRadius: 2,
            background: isDark
              ? `linear-gradient(135deg, ${alpha(theme.palette.primary.main, 0.14)} 0%, ${alpha(theme.palette.primary.dark, 0.12)} 100%)`
              : "linear-gradient(135deg, rgba(76, 175, 80, 0.06) 0%, rgba(46, 125, 50, 0.08) 100%)",
            border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.28 : 0.14)}`,
          }}
        >
          <Typography variant="body2" color="text.secondary" align="center">
            <strong>Admin, reviewer, or partner?</strong>
            <br />
            Use the same sign-in above with your work email. You will be directed to your portal
            dashboard after authentication.
          </Typography>
        </Box>

        <Stack
          direction="row"
          spacing={2}
          justifyContent="center"
          flexWrap="wrap"
          useFlexGap
          sx={{ mt: 3 }}
        >
          <Link
            component={RouterLink}
            to="/privacy-policy"
            variant="caption"
            color="text.secondary"
            sx={{ textDecoration: "none", "&:hover": { textDecoration: "underline" } }}
          >
            Privacy Policy
          </Link>
          <Typography variant="caption" color="text.secondary">
            •
          </Typography>
          <Link
            component={RouterLink}
            to="/terms-of-service"
            variant="caption"
            color="text.secondary"
            sx={{ textDecoration: "none", "&:hover": { textDecoration: "underline" } }}
          >
            Terms of Service
          </Link>
          <Typography variant="caption" color="text.secondary">
            •
          </Typography>
          <Link
            component={RouterLink}
            to="/partners"
            variant="caption"
            color="text.secondary"
            sx={{ textDecoration: "none", "&:hover": { textDecoration: "underline" } }}
          >
            Partner program
          </Link>
          <Typography variant="caption" color="text.secondary">
            •
          </Typography>
          <Link
            component={RouterLink}
            to="/help"
            variant="caption"
            color="text.secondary"
            sx={{ textDecoration: "none", "&:hover": { textDecoration: "underline" } }}
          >
            Help
          </Link>
        </Stack>

        <Typography
          variant="caption"
          color="text.secondary"
          align="center"
          sx={{ display: "block", mt: 1.5 }}
          data-testid="baseline-version-label"
        >
          Baseline Version: {baselineVersion}
        </Typography>
      </Paper>
    </Box>
  );
};

export default UserLogin;
