import React from 'react';
import {
  Alert,
  Box,
  Button,
  Container,
  Link,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import PartnersSubNav from './PartnersSubNav';
import {
  API_USAGE_PRICING_ROWS,
  PARTNER_CONTACT_EMAIL,
  PARTNERSHIP_PRICING_ROWS,
  PARTNER_PROGRAM_SUMMARY,
} from '../../constants/partnerProgram';

const PartnersPage: React.FC = () => {
  return (
    <Box sx={{ minHeight: '100vh', bgcolor: 'background.default', py: 4 }}>
      <Container maxWidth="lg">
        <Stack spacing={3}>
          <Box>
            <Typography variant="h4" component="h1" gutterBottom>
              Partners
            </Typography>
            <Typography variant="body1" color="text.secondary" sx={{ maxWidth: 800 }}>
              {PARTNER_PROGRAM_SUMMARY}
            </Typography>
          </Box>

          <PartnersSubNav />

          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
            <Button variant="contained" component={RouterLink} to="/login">
              Partner portal sign in
            </Button>
            <Button variant="outlined" component={RouterLink} to="/register?type=partner">
              Register as partner
            </Button>
            <Button variant="outlined" component={RouterLink} to="/partners/api-documentation">
              View API documentation
            </Button>
          </Stack>

          <Paper sx={{ p: 3 }}>
            <Typography variant="h5" gutterBottom>
              Partnership costing
            </Typography>
            <Typography variant="body2" color="text.secondary" paragraph>
              Indicative annual platform fees and usage models for banks, auditors, verification agencies, and
              integrators. All amounts are in INR and exclusive of GST. Final quotes depend on cohort size and API
              volume.
            </Typography>
            <TableContainer sx={{ mb: 3 }}>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Partner type</TableCell>
                    <TableCell>Commercial model</TableCell>
                    <TableCell>Annual fee (INR)</TableCell>
                    <TableCell>Usage fee</TableCell>
                    <TableCell>API access</TableCell>
                    <TableCell>Typical scopes</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {PARTNERSHIP_PRICING_ROWS.map((row) => (
                    <TableRow key={row.id}>
                      <TableCell>{row.partnerType}</TableCell>
                      <TableCell>{row.commercialModel}</TableCell>
                      <TableCell>{row.annualFeeInr}</TableCell>
                      <TableCell>{row.usageFee}</TableCell>
                      <TableCell>{row.apiAccess}</TableCell>
                      <TableCell>
                        <Typography variant="caption">{row.typicalScopes}</Typography>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>

            <Typography variant="h6" sx={{ mb: 1 }}>
              API usage overage
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Item</TableCell>
                    <TableCell>Included</TableCell>
                    <TableCell>Overage</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {API_USAGE_PRICING_ROWS.map((row) => (
                    <TableRow key={row.id}>
                      <TableCell>{row.item}</TableCell>
                      <TableCell>{row.included}</TableCell>
                      <TableCell>{row.overage}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>

          <Alert severity="info">
            Ready to integrate?{' '}
            <Link component={RouterLink} to="/register?type=partner">
              Register as a partner
            </Link>{' '}
            to create your portal account and receive scoped API access. For custom commercial terms, email{' '}
            <Link href={`mailto:${PARTNER_CONTACT_EMAIL}?subject=Partnership%20pricing%20enquiry`}>
              {PARTNER_CONTACT_EMAIL}
            </Link>
            .
          </Alert>
        </Stack>
      </Container>
    </Box>
  );
};

export default PartnersPage;
