export type ReadinessLevel = 'aligned' | 'ready' | 'configured' | 'active' | 'connected' | 'data_available' | 'template_ready' | 'datapoints_available' | 'products_registered' | 'applicable' | 'in_progress' | 'needs_improvement' | 'review_required' | 'needs_products' | 'needs_inventory' | 'needs_activity_data' | 'import_only' | 'empty' | 'not_applicable' | 'not_started';

const READINESS_LABELS: Record<ReadinessLevel, string> = {
  aligned: 'Aligned',
  ready: 'Ready',
  configured: 'Configured',
  active: 'Active',
  connected: 'Connected',
  data_available: 'Data available',
  template_ready: 'Template ready',
  datapoints_available: 'Datapoints available',
  products_registered: 'Products registered',
  applicable: 'Applicable',
  in_progress: 'In progress',
  needs_improvement: 'Needs improvement',
  review_required: 'Review required',
  needs_products: 'Needs products',
  needs_inventory: 'Needs inventory',
  needs_activity_data: 'Needs activity data',
  import_only: 'Import only',
  empty: 'Empty',
  not_applicable: 'Not applicable',
  not_started: 'Not started',
};

const isComplianceHubPayload = (value: Record<string, unknown>): boolean =>
  'readiness' in value
  || 'indiaReadiness' in value
  || 'exportReadiness' in value
  || 'modules' in value
  || 'exportProfile' in value;

/** Unwrap compliance-hub API payloads whether nested under `data` or returned flat. */
export const unwrapComplianceHubPayload = <T extends Record<string, unknown>>(
  response: unknown
): T | null => {
  if (!response || typeof response !== 'object') {
    return null;
  }
  let body = response as Record<string, unknown>;
  for (let depth = 0; depth < 3; depth += 1) {
    if (isComplianceHubPayload(body)) {
      return body as T;
    }
    if (body.data && typeof body.data === 'object') {
      body = body.data as Record<string, unknown>;
      continue;
    }
    break;
  }
  return isComplianceHubPayload(body) ? (body as T) : null;
};

const normalizeStatusKey = (level?: string): string | undefined => {
  const trimmed = level?.trim();
  if (!trimmed) {
    return undefined;
  }
  return trimmed.toLowerCase();
};

export interface ComplianceSectionDef {
  id: string;
  label: string;
  description: string;
}

export interface ComplianceSectionGroup {
  id: string;
  label: string;
  sections: ComplianceSectionDef[];
}

export type ComplianceTrackPath = '/compliance/india' | '/compliance/export';

/** Legacy deep links that should resolve to a valid section id. */
export const COMPLIANCE_SECTION_ALIASES: Record<string, string> = {
  pat: 'pat-intensity',
  brsr: 'brsr-core',
  iso: 'iso-assurance',
  iso14064: 'iso-assurance',
  sbti: 'sbti-plans',
  sync: 'data-sync',
  pcf: 'product-pcf',
  portal: 'supplier-portal',
  tcfd: 'tcfd-issb',
  issb: 'tcfd-issb',
};

export const normalizeComplianceSectionId = (
  section: string | null | undefined,
  validSections: readonly string[]
): string | null => {
  const trimmed = section?.trim();
  if (!trimmed) {
    return null;
  }
  if (validSections.includes(trimmed)) {
    return trimmed;
  }
  const alias = COMPLIANCE_SECTION_ALIASES[trimmed.toLowerCase()];
  if (alias && validSections.includes(alias)) {
    return alias;
  }
  return null;
};

export const flattenComplianceSections = (
  groups: readonly ComplianceSectionGroup[]
): ComplianceSectionDef[] => groups.flatMap((group) => group.sections);

export const complianceSectionHref = (
  trackPath: ComplianceTrackPath,
  sectionId: string
): string => {
  if (!sectionId || sectionId === 'overview') {
    return trackPath;
  }
  return `${trackPath}?section=${encodeURIComponent(sectionId)}`;
};

export const findComplianceSectionGroup = (
  groups: readonly ComplianceSectionGroup[],
  sectionId: string
): ComplianceSectionGroup | undefined =>
  groups.find((group) => group.sections.some((section) => section.id === sectionId));

