import React from 'react';
import { Button, Stack } from '@mui/material';
import { Link as RouterLink, useLocation } from 'react-router-dom';

const PARTNERS_SUB_PAGES = [
  { label: 'Partners', path: '/partners' },
  { label: 'API documentation', path: '/partners/api-documentation' },
] as const;

const PartnersSubNav: React.FC = () => {
  const location = useLocation();
  const currentPath = location.pathname.replace(/\/+$/, '') || '/partners';

  return (
    <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap role="navigation" aria-label="Partners section">
      {PARTNERS_SUB_PAGES.map((item) => {
        const isActive = currentPath === item.path;
        return (
          <Button
            key={item.path}
            component={RouterLink}
            to={item.path}
            variant={isActive ? 'contained' : 'outlined'}
            size="small"
          >
            {item.label}
          </Button>
        );
      })}
    </Stack>
  );
};

export default PartnersSubNav;
