import React from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  LinearProgress,
  Stack,
  Typography,
} from '@mui/material';
import { AutoAwesome as AiIcon } from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import type { TrustPanelScores } from '../../utils/sustainabilityUx';

export interface MsmeAdvisoryPayload {
  nextBestAction?: {
    title?: string;
    description?: string;
    path?: string;
    priority?: string;
  };
  trustPanel?: TrustPanelScores;
  outputs?: {
    goalAdvisory?: {
      goalTitle?: string;
      prioritizedActions?: Array<{
        id: string;
        title: string;
        description: string;
        path: string;
        priority: string;
      }>;
    };
    buyerAdvisory?: {
      openRequestCount?: number;
      inbox?: Array<{ buyerName: string; frameworkLabel: string; urgency: string; daysToDue: number | null }>;
    };
    dpdpAdvisory?: {
      status?: string;
      openIssues?: string[];
    };
    environmentalKpi?: {
      summary?: string;
      readinessScore?: number;
    };
  };
}

interface DashboardMsmeAdvisoryPanelProps {
  advisory: MsmeAdvisoryPayload | null;
  loading?: boolean;
  error?: string | null;
}

const levelColor = (level?: string): 'success' | 'warning' | 'error' => {
  if (level === 'high') return 'success';
  if (level === 'medium') return 'warning';
  return 'error';
};

export const DashboardMsmeAdvisoryPanel: React.FC<DashboardMsmeAdvisoryPanelProps> = ({
  advisory,
  loading,
  error,
}) => {
  if (loading) {
    return (
      <Card variant="outlined" sx={{ mb: 3 }}>
        <CardContent>
          <Typography variant="subtitle2" color="text.secondary" gutterBottom>
            AI MSME advisory
          </Typography>
          <LinearProgress />
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Alert severity="warning" sx={{ mb: 3 }}>
        {error}
      </Alert>
    );
  }

  const trust = advisory?.trustPanel;
  const goal = advisory?.outputs?.goalAdvisory;
  const buyer = advisory?.outputs?.buyerAdvisory;
  const dpdp = advisory?.outputs?.dpdpAdvisory;
  const env = advisory?.outputs?.environmentalKpi;
  const hasPrioritizedActions = Boolean(goal?.prioritizedActions && goal.prioritizedActions.length > 0);

  if (!trust && !hasPrioritizedActions && !advisory?.nextBestAction && !buyer && !dpdp && !env) {
    return (
      <Card variant="outlined" sx={{ mb: 3 }}>
        <CardContent>
          <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1 }}>
            <AiIcon color="primary" fontSize="small" />
            <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
              AI MSME advisory
            </Typography>
          </Stack>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Upload transactions or run an assessment to unlock tailored guidance on data quality, buyer requests, and next steps.
          </Typography>
          <Button component={RouterLink} to="/carbon-footprint?section=start-assessment" size="small" variant="outlined">
            Start assessment
          </Button>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card variant="outlined" sx={{ mb: 3, borderColor: 'primary.light' }}>
      <CardContent>
        <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 2 }}>
          <AiIcon color="primary" fontSize="small" />
          <Typography variant="h6" sx={{ fontWeight: 700 }}>
            AI advisory — {goal?.goalTitle || 'Your workspace'}
          </Typography>
        </Stack>

        {trust ? <GridScores trust={trust} /> : null}

        {trust?.uncertaintyNote ? (
          <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1.5 }}>
            {trust?.uncertaintyNote}
          </Typography>
        ) : null}

        {buyer && (buyer.openRequestCount || 0) > 0 ? (
          <Alert severity="info" sx={{ mt: 2 }}>
            {buyer.openRequestCount} open buyer request(s) —{' '}
            <Button component={RouterLink} to="/compliance" size="small">
              Open compliance hub
            </Button>
          </Alert>
        ) : null}

        {dpdp?.openIssues?.length ? (
          <Alert severity="warning" sx={{ mt: 2 }}>
            {dpdp.openIssues[0]}{' '}
            <Button component={RouterLink} to="/data-privacy" size="small">
              Privacy settings
            </Button>
          </Alert>
        ) : null}

        {env?.summary ? (
          <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
            {env.summary}
          </Typography>
        ) : null}

        {goal?.prioritizedActions && goal.prioritizedActions.length > 0 ? (
          <Box sx={{ mt: 2 }}>
            <Typography variant="subtitle2" sx={{ mb: 1 }}>
              Recommended actions
            </Typography>
            <Stack spacing={1}>
              {goal.prioritizedActions.slice(0, 4).map((action) => (
                <Stack
                  key={action.id}
                  direction="row"
                  alignItems="center"
                  justifyContent="space-between"
                  sx={{ py: 0.5 }}
                >
                  <Typography variant="body2">{action.title}</Typography>
                  <Button component={RouterLink} to={action.path} size="small">
                    Go
                  </Button>
                </Stack>
              ))}
            </Stack>
          </Box>
        ) : null}
      </CardContent>
    </Card>
  );
};

const GridScores: React.FC<{ trust: TrustPanelScores }> = ({ trust }) => (
  <Box
    sx={{
      display: 'grid',
      gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' },
      gap: 2,
    }}
  >
    <ScoreBlock
      label="Data completeness"
      score={trust.dataCompletenessScore}
      helper="How much evidence you have uploaded"
    />
    <ScoreBlock
      label="Inventory quality"
      score={trust.inventoryQualityScore}
      helper={
        typeof trust.activitySharePct === 'number'
          ? `Activity-based data: ${trust.activitySharePct}% of transactions`
          : 'Method rigor for assurance and buyers'
      }
      chip={trust.inventoryQualityLevel}
      chipColor={levelColor(trust.inventoryQualityLevel)}
    />
  </Box>
);

const ScoreBlock: React.FC<{
  label: string;
  score: number;
  helper: string;
  chip?: string;
  chipColor?: 'success' | 'warning' | 'error';
}> = ({ label, score, helper, chip, chipColor }) => (
  <Box>
    <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ mb: 0.5 }}>
      <Typography variant="subtitle2">{label}</Typography>
      {chip ? <Chip size="small" label={chip} color={chipColor} variant="outlined" /> : null}
    </Stack>
    <LinearProgress variant="determinate" value={score} sx={{ height: 8, borderRadius: 2, mb: 0.5 }} />
    <Typography variant="caption" color="text.secondary">
      {score}% — {helper}
    </Typography>
  </Box>
);
